"""Tests for MocapLipsyncService: phoneme tokens to visemes, CTC decoding and the viseme curves."""

import json
import os
import sys

import numpy as np
import pytest

from .. import dynamic_import, LocationService

MocapLipsyncService = dynamic_import("mpfb.services.mocaplipsyncservice", "MocapLipsyncService")
_MODULE = sys.modules[MocapLipsyncService.__module__]
VISEMES = _MODULE.LIPSYNC_VISEMES


def _write_audio_source(path, sequence, tokens, start=1.0, frame_seconds=0.02):
    """A *_logits.npz like the worker writes it, with the given best token in every 20 ms frame."""
    logprobs = np.full((len(sequence), len(tokens)), -10.0, dtype=np.float32)
    for frame, token in enumerate(sequence):
        logprobs[frame, token] = 0.0
    np.savez(path, logprobs=logprobs.astype(np.float16), frame_times=start + (np.arange(len(sequence)) + 0.5) * frame_seconds,
             tokens=np.array(tokens), blank=0, frame_seconds=frame_seconds)
    return str(path)


def test_service_is_not_instanced():
    with pytest.raises(RuntimeError):
        MocapLipsyncService()


@pytest.mark.parametrize("token,visemes", [
    ("m", ["viseme_PP"]), ("f", ["viseme_FF"]), ("ð", ["viseme_TH"]), ("t", ["viseme_DD"]), ("k", ["viseme_kk"]),
    ("tʃ", ["viseme_CH"]), ("ts", ["viseme_SS"]), ("n", ["viseme_nn"]), ("r", ["viseme_RR"]),
    ("a", ["viseme_aa"]), ("ɛ", ["viseme_E"]), ("iː", ["viseme_I"]), ("ɔ", ["viseme_O"]), ("u", ["viseme_U"]),
    ("aɪ", ["viseme_aa", "viseme_I"]), ("oʊ", ["viseme_O", "viseme_U"]),
    ("r̝", ["viseme_RR"]), ("ɲ", ["viseme_nn"]), ("c", ["viseme_DD"]), ("ɟ", ["viseme_DD"]), ("x", ["viseme_kk"]),
    ("i5", ["viseme_I"]), ("tʰ", ["viseme_DD"]), ("nʲ", ["viseme_nn"]), ("ɑ̃", ["viseme_aa"]),
    ("h", []), ("ʔ", []), ("<pad>", []),
    ])
def test_visemes_for_token(token, visemes):
    assert MocapLipsyncService.visemes_for_token(token) == visemes


def test_every_token_of_the_model_has_a_viseme_or_none_on_purpose():
    path = LocationService.get_mpfb_data(os.path.join("ai_models", "wav2vec2-xlsr-53-espeak-cv-ft", "vocab.json"))
    if not os.path.isfile(path):
        pytest.skip("The wav2vec2 model is not in data/ai_models")
    with open(path, "r", encoding="utf-8") as vocab_file:
        tokens = list(json.load(vocab_file))
    assert [token for token in tokens if MocapLipsyncService.visemes_for_token(token) is None] == []


def test_ctc_decoding():
    tokens = ["<pad>", "m", "a"]
    logprobs = np.full((8, 3), -10.0)
    for frame, token in enumerate([0, 1, 1, 0, 2, 2, 2, 0]):
        logprobs[frame, token] = 0.0
    segments = MocapLipsyncService.decode_segments(logprobs, tokens, 0, 0.02, 1.0)
    assert [token for _start, _end, token in segments] == ["m", "a"]
    assert segments[0][0] == pytest.approx(1.02)
    assert segments[1][1] == pytest.approx(1.14)


def test_short_pauses_are_bridged_and_diphthongs_split():
    segments = [(1.0, 1.06, "m"), (1.1, 1.2, "aɪ"), (1.8, 1.9, "s")]
    events, unknown = MocapLipsyncService.viseme_events(segments)
    assert [viseme for viseme, _start, _end in events] == ["viseme_PP", "viseme_aa", "viseme_I", "viseme_SS"]
    assert events[0][2] == pytest.approx(1.1)      # 40 ms pause bridged
    assert events[2][2] == pytest.approx(1.2)      # 600 ms pause kept
    assert unknown == []


def test_curves_lead_the_sound_and_never_sum_over_one():
    events = [("viseme_PP", 1.0, 1.1), ("viseme_aa", 1.1, 1.3)]
    times = np.arange(0.8, 1.6, 0.01)
    weights = MocapLipsyncService.viseme_curves(events, times, {"lead": 0.05, "transition": 0.05, "strength": 1.0})
    pp = weights[:, VISEMES.index("viseme_PP")]
    assert pp[np.searchsorted(times, 0.96)] == pytest.approx(1.0, abs=0.05)  # fully open before the sound at 1.0
    assert weights.sum(axis=1).max() <= 1.0 + 1e-9
    assert weights[np.searchsorted(times, 1.55)].sum() == 0.0


def test_lipsync_curves_from_audio_source(tmp_path):
    tokens = ["<pad>", "m", "a", "aɪ", "ts"]
    sequence = [0] * 10 + [1] * 3 + [0] * 2 + [2] * 6 + [0] * 3 + [3] * 8 + [0] * 30 + [4] * 4 + [0] * 10
    path = _write_audio_source(tmp_path / "audio_line_logits.npz", sequence, tokens)
    curves = MocapLipsyncService.prepare_lipsync_curves(path, {}, 30.0)
    assert curves["names"] == VISEMES
    assert curves["start"] == pytest.approx(1.0)
    assert curves["frames"] == int(len(sequence) * 0.02 * 30) + 1
    assert curves["phonemes"] == 4
    assert curves["values"][:, VISEMES.index("viseme_SS")].max() > 0.9


def test_silent_audio_is_rejected(tmp_path):
    path = _write_audio_source(tmp_path / "silence_logits.npz", [0] * 50, ["<pad>", "a"])
    with pytest.raises(ValueError):
        MocapLipsyncService.prepare_lipsync_curves(path, {}, 30.0)


def test_speech_face_units_keep_the_expression():
    assert "jawOpen" in _MODULE.SPEECH_FACEUNITS
    assert "mouthSmileLeft" not in _MODULE.SPEECH_FACEUNITS
    assert "browInnerUp" not in _MODULE.SPEECH_FACEUNITS
